// [15/09/2026 UTC RODADA 65 (2ª correção)] ALTERADO — pedido verbatim do
// usuário (repetido — o mesmo erro "this._componentsSummaryHtml is not a
// function" continuava aparecendo mesmo DEPOIS da correção de código da
// v465, já commitada e verificada correta no disco por leitura direta do
// arquivo). CAUSA RAIZ REAL (diferente da correção anterior, que era
// legítima mas não bastou sozinha): `cache.addAll(APP_SHELL)` cria
// requisições de rede SEM forçar bypass do cache HTTP comum do navegador
// (`Cache.addAll` não usa `cache:'reload'` por padrão) — mesmo com
// `CACHE_VERSION` incrementado (o que corretamente abre um cache NOVO,
// `caches.open(CACHE_VERSION)`, e descarta o antigo no 'activate' logo
// abaixo), a busca de CADA arquivo durante a instalação podia acabar
// respondida pelo cache HTTP comum do navegador com a versão ANTIGA de
// `js/view3d.js`/`js/mapview.js` (se o navegador ainda considerasse aquela
// resposta HTTP "fresca" por Cache-Control/heurística) — resultado: o
// Service Worker "atualiza" (novo `CACHE_VERSION`, ativa, assume controle),
// mas guarda os MESMOS bytes antigos por trás, então mesmo depois de
// recarregar a página (1x ou várias) o bug persistia, porque o código
// dentro do cache do Service Worker nunca tinha mudado de verdade. CORRIGIDO:
// cada arquivo do `APP_SHELL` agora é buscado individualmente com
// `fetch(url, {cache:'reload'})` — força o navegador a ignorar seu cache
// HTTP comum e buscar sempre a resposta mais nova do servidor para ESTA
// instalação do Service Worker — só então grava no cache novo
// (`cache.put`). Resolve de forma permanente (não só para este bug
// específico) o padrão "o código já está corrigido no disco, mas o
// navegador continua rodando a versão antiga mesmo depois de recarregar",
// que já tinha aparecido antes nesta sessão (RODADA SEGUINTE, v461,
// documentada acima) por outro motivo (esquecer de bumpar o
// CACHE_VERSION) — agora os dois motivos possíveis estão cobertos.
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_VERSION)
      .then((cache) => Promise.all(APP_SHELL.map((url) => fetch(url, { cache: 'reload' }).then((res) => cache.put(url, res)))))
      .then(() => self.skipWaiting()),
  );
});
 
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});
 
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
 
  const url = new URL(req.url);
  const isSameOrigin = url.origin === self.location.origin;
  // Navegação de verdade (abrir/recarregar a página, F5, digitar a URL) —
  // diferente do resto do app-shell (JS/CSS/libs), que é cache-first pra
  // abrir rápido e funcionar offline, ESTA aqui vai pra REDE primeiro. É a
  // peça que faltava pra "impedir que carregue uma página antiga em vez da
  // nova" sem depender só do navegador decidir sozinho quando checar o
  // Service Worker de novo (ver também `updateViaCache:'none'` e o
  // recarregamento automático em app.js `_registerServiceWorker`): com
  // internet, o HTML mais novo do servidor SEMPRE vence; só cai pro cache
  // (pra continuar funcionando offline) se a rede falhar de verdade.
  const isNavigation = isSameOrigin && (req.mode === 'navigate' || url.pathname === '/' || url.pathname.endsWith('/index.html'));
 
  if (isNavigation) {
    event.respondWith(
      fetch(req).then((res) => {
        if (res && res.ok) caches.open(CACHE_VERSION).then((c) => c.put(req, res.clone()));
        return res;
      }).catch(() => caches.match(req).then((cached) => cached || caches.match('./index.html'))),
    );
  } else if (isSameOrigin) {
    // [16/09/2026 UTC] REESCRITO — pedido verbatim do usuário: "Implemente
    // o network-first se ainda não estiver implementado. Para que, tendo
    // acesso a internet, pegue os arquivos do servidor. Caso não tenha
    // acesso a internet, então, pega os arquivos do cache local." Antes
    // desta rodada, o app-shell inteiro (todo `js/*`, incluindo os
    // arquivos MAIS editados desta sessão, como `view3d.js`) era
    // CACHE-FIRST com atualização em segundo plano (servia o cache na
    // hora, buscava a versão nova da rede só depois, em paralelo) — e essa
    // é a causa raiz, documentada repetidas vezes no histórico de
    // `CACHE_VERSION` acima (v461, v465, v466, v468, v469...), do usuário
    // ter que fazer Ctrl+Shift+R toda vez que um `.js` mudava, mesmo já
    // tendo o bump de versão: o cache-first sempre respondia com o
    // conteúdo ANTIGO daquele carregamento específico (só a próxima
    // navegação já pegaria o atualizado, guardado em segundo plano).
    // NETWORK-FIRST resolve isso de vez, exatamente como pedido: com
    // internet, o arquivo mais novo do SERVIDOR sempre vence (mesmo
    // princípio que a navegação, ver bloco `isNavigation` acima, já fazia
    // só pro HTML); sem internet de verdade (a `fetch` rejeita), cai pro
    // cache local — o app continua funcionando 100% offline, igual antes.
    // Único trade-off (aceito a pedido explícito do usuário, priorizando
    // estar sempre atualizado em vez de abrir 1 quadro mais rápido): cada
    // arquivo agora espera a rede responder (ou falhar de vez) antes de
    // decidir — imperceptível com internet normal, só fica mais lento que
    // antes se a rede estiver MUITO lenta (não offline, só lenta).
    event.respondWith(
      fetch(req).then((res) => {
        if (res && res.ok) caches.open(CACHE_VERSION).then((c) => c.put(req, res.clone()));
        return res;
      }).catch(() => caches.match(req)),
    );
  }
});